const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const defaultCategories=['数码','家用电器','衣物','宠物用品','护肤个护','耗材','杂物'];
const defaultFieldOptions={
  衣物:{subcategory:['睡裙','睡衣','上衣','下装','裙子','鞋子','外套','内裤','内衣','床品','内搭','运动衣','拖鞋','袜子'],usageStatus:['使用中','未使用','已闲置','已丢掉'],season:['春秋','夏','冬','四季通用','秋'],unit:['件','个','条','双','副','套']},
  数码:{status:['使用中','未使用','已闲置','已损坏','已出掉'],purchaseChannel:['淘宝','京东','闲鱼','拼多多','阿里巴巴','线下','他人赠予','小红书','抖音','品牌官网']},
  宠物用品:{subcategory:['猫粮','猫砂','保健药','玩具','驱虫药','物品']},
  护肤个护:{usageStatus:['未使用','使用中','已用完'],purchaseChannel:['淘宝','线下','小红书','中免小程序']},
  家用电器:{usageStatus:['使用中','未使用','已闲置','已损坏','已出掉'],purchaseChannel:['淘宝','京东','闲鱼','拼多多','线下','他人赠予','品牌官网']},
  杂物:{usageStatus:['使用中','未使用','已闲置','已丢掉']}
};
const fieldLabels={subcategory:'细分品类',usageStatus:'使用状态',status:'状态',season:'适合季节',unit:'单位',purchaseChannel:'购买途径'};
let state={version:4,items:[],categories:[...defaultCategories],fieldOptions:structuredClone(defaultFieldOptions),challenges:[{id:'no-spend',name:'不消费的一年',emoji:'🌿',checks:[]}],memos:[],updatedAt:Date.now()};
let page='dashboard',query='',category='全部',subCategory='',editing=null,db,dashboardMonth=new Date(),categoryDisplay='visual',selectedItems=new Set(),electronicsSort='days-desc',returnContext=null,itemDisplay='compact',fieldFilters={subcategory:'',status:'',season:'',unit:'',purchaseChannel:''};
const dateKey=(d=new Date())=>{const x=new Date(d),p=n=>String(n).padStart(2,'0');return`${x.getFullYear()}-${p(x.getMonth()+1)}-${p(x.getDate())}`};
const money=n=>`¥${Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}`;
const daysHeld=item=>Math.max(1,Math.floor((Date.now()-new Date(item.startDate||item.purchaseDate||Date.now()))/86400000)+1);
const dailyCost=item=>Number(item.price||0)/daysHeld(item);
const noteValue=(notes,label)=>String(notes||'').split(/\r?\n/).find(line=>line.startsWith(`${label}：`))?.slice(label.length+1).trim()||'';
const itemSubcategory=item=>item.subcategory||noteValue(item.notes,'细分品类')||'未分类';
function normalize(data={}){const items=Array.isArray(data.items)?data.items.map(item=>({...item,subcategory:item.subcategory||noteValue(item.notes,'细分品类')||'',usageStatus:item.usageStatus||noteValue(item.notes,'使用状态')||'',status:item.status||noteValue(item.notes,'状态')||'',season:item.season||noteValue(item.notes,'适合季节')||'',unit:item.unit||noteValue(item.notes,'单位')||'',purchaseChannel:item.purchaseChannel||noteValue(item.notes,'购买途径')||noteValue(item.notes,'购买渠道')||'',startDate:item.startDate||item.purchaseDate||dateKey()})):[],used=items.map(item=>item.category).filter(Boolean),custom=Array.isArray(data.categories)?data.categories:defaultCategories,categories=[...new Set([...custom,...used].map(x=>String(x).trim()).filter(Boolean))],fieldOptions=structuredClone(defaultFieldOptions);if(data.fieldOptions&&typeof data.fieldOptions==='object')Object.entries(data.fieldOptions).forEach(([cat,fields])=>{fieldOptions[cat]??={};Object.entries(fields||{}).forEach(([field,values])=>fieldOptions[cat][field]=[...new Set((Array.isArray(values)?values:[]).map(String).map(x=>x.trim()).filter(Boolean))])});return{version:4,items,categories:categories.length?categories:[...defaultCategories],fieldOptions,challenges:Array.isArray(data.challenges)&&data.challenges.length?data.challenges:[{id:'no-spend',name:'不消费的一年',emoji:'🌿',checks:[]}],memos:Array.isArray(data.memos)?data.memos.map(m=>({...m,id:m.id||uid(),date:m.date||dateKey(),text:String(m.text||'').trim()})).filter(m=>m.text):[],updatedAt:data.updatedAt||Date.now()}}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('home-inventory-ledger',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbGet(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function save(){state.updatedAt=Date.now();return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(structuredClone(state),'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),2200)}
function nav(){return`<nav class="nav">${[['dashboard','⌂','总览'],['calendar','▦','日历备忘'],['items','▤','全部物品'],['challenges','✓','挑战打卡']].map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="navIcon">${icon}</span>${label}</button>`).join('')}<button data-export><span class="navIcon">⇩</span>导出备份</button><button data-import><span class="navIcon">⇧</span>恢复备份</button>${page==='dashboard'?`<div class="sideTools"><span class="eyebrow">QUICK ADD</span><h3>快速记录</h3><div class="sideQuick">${['数码','衣物','耗材'].map(c=>`<button data-add data-category="${c}"><span>${itemIcon(c)}</span><b>${c}</b></button>`).join('')}</div><div class="sideChallenge"><small>DAILY CHECK-IN · ${state.challenges.length} 项</small><div class="sideChallengeList">${state.challenges.map(c=>{const done=(c.checks||[]).includes(dateKey());return`<div class="sideChallengeEntry"><button class="sideChallengeName" data-challenge-detail="${esc(c.id)}">${esc(c.emoji||'✓')} ${esc(c.name)}<small>累计 ${(c.checks||[]).length} 天 · 查看月历 ›</small></button><button class="sideCheck ${done?'done':''}" data-check="${esc(c.id)}">${done?'✓ 已打卡':'今日打卡'}</button></div>`}).join('')}</div><button class="sideManage" data-page="challenges">管理全部挑战</button></div></div>`:''}</nav>`}
function bottomNav(){return`<nav class="bottomNav">${[['dashboard','⌂','总览'],['calendar','▦','日历'],['items','▤','物品'],['challenges','✓','打卡']].map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><b>${icon}</b>${label}</button>`).join('')}</nav>`}
function header(){return`<header class="top"><div class="brand"><span class="logo">⌂</span><div><small>HOME LEDGER</small><h1>家物簿</h1></div></div><div class="topActions"><button class="ghostBtn" data-export>导出</button><button class="iconBtn" data-add aria-label="添加物品">＋</button></div></header>`}
function itemIcon(cat){return({数码:'⌨',家用电器:'♨',衣物:'♧',宠物用品:'♢',护肤个护:'✦',耗材:'◫',杂物:'◇'})[cat]||'◇'}
function expiryBadge(item){if(!item.expiryDate)return'';const days=Math.ceil((new Date(item.expiryDate)-new Date(dateKey()))/86400000);if(days<0)return'<span class="badge danger">已过期</span>';if(days<=30)return`<span class="badge warn">${days}天后到期</span>`;return''}
function itemRow(item){return`<button class="itemRow" data-edit="${item.id}"><span class="thumb">${item.photo?`<img src="${item.photo}" alt="">`:itemIcon(item.category)}</span><span><b>${esc(item.name)}</b><small>${esc(item.category)} · ${daysHeld(item)}天 · ${esc(item.location||'未设置位置')}</small></span><span class="cost">${money(dailyCost(item))}/天</span></button>`}
function itemCard(item){return`<article class="itemCard"><button class="itemPhoto" data-edit="${item.id}">${item.photo?`<img src="${item.photo}" alt="${esc(item.name)}">`:itemIcon(item.category)}</button><div class="itemBody"><span class="badge">${esc(item.category)}</span>${expiryBadge(item)}<b>${esc(item.name)}</b><div class="itemMeta"><span>持有 ${daysHeld(item)} 天</span><span>${money(item.price)}</span></div><div class="itemMeta"><span>${esc(item.location||'未设置位置')}</span><strong>${money(dailyCost(item))}/天</strong></div></div></article>`}
function categoryData(){const map=new Map;state.items.forEach(i=>map.set(i.category,(map.get(i.category)||0)+1));return[...map.entries()].sort((a,b)=>b[1]-a[1])}
function dashboard(){const total=state.items.length,value=state.items.reduce((s,i)=>s+Number(i.price||0)*Number(i.quantity||1),0),expiring=state.items.filter(i=>i.expiryDate&&new Date(i.expiryDate)-Date.now()<30*86400000).length,avg=total?state.items.reduce((s,i)=>s+daysHeld(i),0)/total:0,recent=[...state.items].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,5),cats=categoryData(),max=Math.max(1,...cats.map(x=>x[1])),challenge=state.challenges[0]||{checks:[],name:'暂无挑战'},checked=challenge.checks.includes(dateKey()),yearProgress=Math.round(challenge.checks.filter(d=>d.startsWith(String(new Date().getFullYear()))).length/365*100);return`<div class="pageHead"><div><span class="eyebrow">HOUSEHOLD OVERVIEW</span><h2>把拥有的东西，过成明白的生活</h2><p>管理物品、看懂成本，也记录每一次克制。</p></div><span class="dateBadge">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span></div><section class="stats"><div class="stat"><span>家庭物品</span><strong>${total}</strong><small>件已记录</small></div><div class="stat"><span>购入总额</span><strong>${money(value)}</strong><small>按数量计算</small></div><div class="stat"><span>即将到期</span><strong>${expiring}</strong><small>未来30天</small></div><div class="stat"><span>平均持有</span><strong>${Math.round(avg)}</strong><small>天</small></div></section><div class="grid2"><section class="panel"><div class="panelHead"><h3>快速记录</h3><span>选择类型开始</span></div><div class="quickAdd">${['数码','衣物','耗材'].map(c=>`<button data-add data-category="${c}"><b>${itemIcon(c)} ${c}</b><small>${c==='耗材'?'记录库存和有效期':'计算持有天数与日均成本'}</small></button>`).join('')}</div><div class="panelHead" style="margin-top:22px"><h3>最近更新</h3><button class="ghostBtn" data-page="items">查看全部</button></div><div class="recentList">${recent.length?recent.map(itemRow).join(''):'<div class="empty"><div class="emptyIcon">⌂</div><b>还没有物品</b><p>点击右上角加号，记录第一件物品。</p></div>'}</div></section><aside><section class="challengeHero"><small>年度挑战</small><strong>${esc(challenge.name)}</strong><span>今年已坚持 ${challenge.checks.filter(d=>d.startsWith(String(new Date().getFullYear()))).length} 天</span><div class="progress"><i style="width:${yearProgress}%"></i></div><button class="checkBtn ${checked?'done':''}" data-check="${challenge.id}">${checked?'✓ 今天已打卡':'今天没有非必要消费'}</button></section><section class="panel" style="margin-top:18px"><div class="panelHead"><h3>分类分布</h3><span>${cats.length} 类</span></div><div class="categoryBars">${cats.length?cats.slice(0,7).map(([name,count])=>`<div class="barLine"><span>${esc(name)}</span><div class="bar"><i style="width:${count/max*100}%"></i></div><b>${count}</b></div>`).join(''):'<p style="color:var(--sub)">添加物品后自动生成统计。</p>'}</div></section></aside></div>`}
function itemsPage(){const filtered=state.items.filter(i=>(category==='全部'||i.category===category)&&[i.name,i.category,i.location,i.notes].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));return`<div class="pageHead"><div><span class="eyebrow">INVENTORY</span><h2>全部物品</h2><p>查找位置、使用时间、价格与使用成本。</p></div><button class="ghostBtn" data-manage-categories>管理分类</button></div><div class="toolbar"><input id="search" class="input" value="${esc(query)}" placeholder="搜索名称、位置或备注"><select id="categoryFilter" class="select"><option>全部</option>${state.categories.map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="primaryBtn" data-add>＋ 添加物品</button></div><div class="itemsGrid">${filtered.length?filtered.map(itemCard).join(''):`<div class="empty" style="grid-column:1/-1"><div class="emptyIcon">⌕</div><b>没有找到物品</b><p>换个关键词或添加新的物品。</p></div>`}</div>`}
function monthCells(checks){const now=new Date(),y=now.getFullYear(),m=now.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();let html='<span style="visibility:hidden"></span>'.repeat(first);for(let d=1;d<=days;d++){const k=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;html+=`<span class="${checks.includes(k)?'checked':''} ${k===dateKey()?'today':''}">${d}</span>`}return html}
function challengesPage(){return`<div class="pageHead"><div><span class="eyebrow">MINDFUL LIVING</span><h2>挑战打卡</h2><p>每个挑战独立记录，点击名称查看完整月历。</p></div><button class="primaryBtn" data-new-challenge>＋ 新挑战</button></div><div class="challengeGrid">${state.challenges.map(c=>{const done=(c.checks||[]).includes(dateKey());return`<article class="challengeCard"><div class="challengeCardTop"><button class="challengeTitle" data-challenge-detail="${esc(c.id)}"><span>${esc(c.emoji||'✓')}</span><strong>${esc(c.name)}</strong><small>查看打卡记录 ›</small></button><button class="dangerBtn" data-delete-challenge="${esc(c.id)}" aria-label="删除挑战">删除</button></div><p>本月完成 ${(c.checks||[]).filter(d=>d.startsWith(dateKey().slice(0,7))).length} 天 · 累计 ${(c.checks||[]).length} 天</p><button class="checkBtn ${done?'done':''}" data-check="${esc(c.id)}">${done?'✓ 今天已完成':'完成今天的打卡'}</button></article>`}).join('')}</div>`}
let challengeMonth=new Date();
function challengeDetail(id){const c=state.challenges.find(x=>x.id===id);if(!c)return;document.querySelector('.challengeDetailOverlay')?.remove();const y=challengeMonth.getFullYear(),m=challengeMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),checks=c.checks||[];let cells='<span class="calendarBlank"></span>'.repeat(first);for(let d=1;d<=days;d++){const key=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells+=`<button class="memoDay challengeDay ${checks.includes(key)?'checked':''} ${key===dateKey()?'today':''}" data-challenge-date="${key}" data-challenge-id="${esc(id)}"><b>${d}</b>${checks.includes(key)?'<span>✓ 已打卡</span>':''}</button>`}document.body.insertAdjacentHTML('beforeend',`<section class="overlay challengeDetailOverlay"><div class="modal"><div class="modalHead"><button class="ghostBtn" data-close-challenge-detail>返回</button><h2>${esc(c.name)}</h2><span>${checks.length} 天</span></div><div class="modalBody"><div class="moduleHead"><p>点击日期可补打卡或取消记录</p><div class="calendarNav"><button data-challenge-month="-1" data-challenge-id="${esc(id)}">‹</button><strong>${y}年${m+1}月</strong><button data-challenge-month="1" data-challenge-id="${esc(id)}">›</button></div></div><div class="weekHead">${['日','一','二','三','四','五','六'].map(x=>`<span>周${x}</span>`).join('')}</div><div class="memoCalendar">${cells}</div><p class="moduleHint">本月已打卡 ${checks.filter(d=>d.startsWith(`${y}-${String(m+1).padStart(2,'0')}`)).length} 天</p></div></div></section>`)}
function dashboardChallenges(){return`<section class="panel dashboardChallenges"><div class="moduleHead"><div><span class="eyebrow">DAILY CHECK-IN</span><h3>挑战打卡记录</h3></div><button class="ghostBtn" data-page="challenges">管理挑战</button></div><div class="dashboardChallengeList">${state.challenges.map(c=>{const done=(c.checks||[]).includes(dateKey());return`<div class="dashboardChallenge"><button class="challengeTitle" data-challenge-detail="${esc(c.id)}"><span>${esc(c.emoji||'✓')}</span><strong>${esc(c.name)}</strong><small>累计 ${(c.checks||[]).length} 天 · 查看月历 ›</small></button><button class="checkBtn ${done?'done':''}" data-check="${esc(c.id)}">${done?'✓ 已打卡':'今日打卡'}</button></div>`}).join('')}</div></section>`}

function calendarPage(){return`<div class="pageHead"><div><span class="eyebrow">DAILY NOTES</span><h2>日历备忘</h2><p>独立月历 · 点击日期查看、添加或删除备忘。</p></div></div>${dashboardCalendar()}` }
function content(){return page==='items'?itemsPage():page==='challenges'?challengesPage():page==='calendar'?calendarPage():dashboard()}
function render(){document.title=`家物簿 · ${page==='dashboard'?'总览':page==='items'?'物品':page==='calendar'?'日历':'打卡'}`;$('#app').innerHTML=`<div class="shell">${header()}<div class="layout">${nav()}<main class="main pageFade">${content()}</main></div>${bottomNav()}</div>`}
function openInventoryFromDashboard(cat,sub=''){returnContext={page:'dashboard',scrollY:scrollY};category=cat;subCategory=sub;Object.keys(fieldFilters).forEach(key=>fieldFilters[key]='');page='items';if(location.hash!=='#inventory')history.pushState({inventoryView:true},'','#inventory');render();scrollTo({top:0,behavior:'smooth'})}
function restorePreviousView(){const target=returnContext||{page:'dashboard',scrollY:0};returnContext=null;page=target.page;subCategory='';render();requestAnimationFrame(()=>scrollTo({top:target.scrollY||0,behavior:'auto'}))}
function editor(id='',preset=''){const old=state.items.find(i=>i.id===id),fallback=state.categories[0]||'未分类',item=old?structuredClone(old):{id:uid(),name:'',category:preset&&state.categories.includes(preset)?preset:fallback,startDate:dateKey(),price:'',quantity:1,location:'',expiryDate:'',warrantyDate:'',notes:'',photo:'',createdAt:Date.now(),updatedAt:Date.now()};editing=item;document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><form class="modal" id="itemForm"><div class="modalHead"><button type="button" class="ghostBtn" data-close>取消</button><h2>${old?'编辑物品':'新建物品'}</h2><button class="primaryBtn" type="submit">保存</button></div><div class="modalBody"><div class="formGrid"><div class="field full"><label>照片</label><label class="photoPick">${item.photo?`<img src="${item.photo}" alt="">`:'<span>＋ 添加物品照片</span>'}<input id="photoInput" type="file" accept="image/*"></label></div><div class="field"><label>名称 *</label><input class="input" name="name" value="${esc(item.name)}" required placeholder="例如：空气净化器"></div><div class="field"><div class="labelLine"><label>分类</label><button type="button" class="miniTextBtn" data-manage-categories>管理分类</button></div><select class="select" name="category" id="itemCategory">${state.categories.map(c=>`<option ${item.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>使用日期</label><input class="input" name="startDate" type="date" value="${esc(item.startDate||item.purchaseDate||dateKey())}"></div><div class="field"><label>购买价格</label><input class="input" name="price" type="number" min="0" step="0.01" value="${esc(item.price)}" placeholder="0.00"></div><div class="field"><label>数量</label><input class="input" name="quantity" type="number" min="1" value="${esc(item.quantity)}"></div><div class="field"><label>存放位置</label><input class="input" name="location" value="${esc(item.location)}" placeholder="例如：客厅电视柜"></div><div class="field"><label>有效期</label><input class="input" name="expiryDate" type="date" value="${esc(item.expiryDate)}"></div><div class="field"><label>保修截止</label><input class="input" name="warrantyDate" type="date" value="${esc(item.warrantyDate)}"></div><div class="field full"><label>备注</label><textarea class="textarea" name="notes" placeholder="型号、购买渠道、使用感受……">${esc(item.notes)}</textarea></div></div><div class="modalActions">${old?'<button type="button" class="dangerBtn" data-delete>删除物品</button>':'<span></span>'}<span style="color:var(--sub);font-size:13px">数据仅保存在当前浏览器</span></div></div></form></section>`)}
function close(){document.querySelector('.overlay')?.remove();editing=null}
function categoryManager(){document.querySelector('.categoryOverlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<section class="overlay categoryOverlay"><div class="modal categoryModal"><div class="modalHead"><button type="button" class="ghostBtn" data-close-category>完成</button><h2>管理分类</h2><span class="categoryCount">${state.categories.length} 个</span></div><div class="modalBody"><form id="categoryAddForm" class="categoryAdd"><input class="input" name="categoryName" maxlength="20" placeholder="输入新分类名称" required><button class="primaryBtn" type="submit">＋ 新增</button></form><div class="categoryList">${state.categories.map((name,index)=>{const used=state.items.filter(item=>item.category===name).length;return`<div class="categoryRow" data-category-row><span class="categoryOrder">${index+1}</span><input class="input" value="${esc(name)}" maxlength="20" aria-label="分类名称"><span class="categoryUsed">${used} 件</span><button class="secondaryBtn" data-secondary-category="${esc(name)}">二类项目</button><button class="ghostBtn" data-rename-category="${esc(name)}">保存</button><button class="dangerBtn" data-delete-category="${esc(name)}" ${used?'disabled title="使用中的分类不能删除"':''}>删除</button></div>`}).join('')}</div><p class="categoryHint">每个一级分类都可管理细分品类；衣物还可管理季节、状态和单位。重命名会同步已有物品。</p></div></div></section>`)}

function secondaryManager(cat){const fields=categoryFieldProfile(cat);document.body.insertAdjacentHTML('beforeend',`<section class="overlay secondaryOverlay"><div class="modal secondaryModal"><div class="modalHead"><button type="button" class="ghostBtn" data-close-secondary>返回</button><h2>${esc(cat)} · 二类项目</h2><span>${fields.length} 组</span></div><div class="modalBody secondaryGroups">${fields.map(field=>{const values=fieldOptions(cat,field);return`<section class="secondaryGroup"><div><h3>${fieldLabels[field]}</h3><p>${values.length} 个选项</p></div><div class="optionChips">${values.slice(0,8).map(v=>`<span>${esc(v)}</span>`).join('')}${values.length>8?`<span>＋${values.length-8}</span>`:''}</div><button class="ghostBtn" data-manage-field="${field}" data-field-category="${esc(cat)}">管理</button></section>`}).join('')}</div></div></section>`)}
function refreshCategorySelect(){const select=$('#itemCategory');if(!select)return;select.innerHTML=state.categories.map(c=>`<option ${editing?.category===c?'selected':''}>${esc(c)}</option>`).join('')}
async function resizeImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const max=1100,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.78))};img.onerror=reject;img.src=url})}
function exportData(){const blob=new Blob([JSON.stringify({...state,app:'home-inventory-ledger',exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`家物簿完整备份-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-manage-categories')){e.preventDefault();if(editing&&$('#itemCategory'))editing.category=$('#itemCategory').value;categoryManager()}else if(t.hasAttribute('data-close-category')){document.querySelector('.categoryOverlay')?.remove();refreshCategorySelect();if(page==='items'&&!editing)render()}else if(t.dataset.renameCategory!==undefined){e.preventDefault();const old=t.dataset.renameCategory,row=t.closest('[data-category-row]'),next=row.querySelector('input').value.trim();if(!next)return toast('分类名称不能为空');if(next!==old&&state.categories.includes(next))return toast('这个分类已经存在');state.categories=state.categories.map(name=>name===old?next:name);state.items=state.items.map(item=>item.category===old?{...item,category:next}:item);if(state.fieldOptions[old]&&next!==old){state.fieldOptions[next]=state.fieldOptions[old];delete state.fieldOptions[old]}if(editing?.category===old)editing.category=next;if(category===old)category=next;await save();categoryManager();refreshCategorySelect();toast('分类名称已更新')}else if(t.dataset.deleteCategory!==undefined){e.preventDefault();const name=t.dataset.deleteCategory;if(state.items.some(item=>item.category===name))return toast('该分类仍有物品，暂时不能删除');if(state.categories.length===1)return toast('至少保留一个分类');if(!confirm(`确定删除分类“${name}”？`))return;state.categories=state.categories.filter(item=>item!==name);delete state.fieldOptions[name];if(editing?.category===name)editing.category=state.categories[0];if(category===name)category='全部';await save();categoryManager();refreshCategorySelect();toast('分类已删除')}});
document.addEventListener('submit',async e=>{if(e.target.id!=='categoryAddForm')return;e.preventDefault();const name=new FormData(e.target).get('categoryName').trim();if(!name)return;if(state.categories.includes(name))return toast('这个分类已经存在');state.categories.push(name);if(editing&&!editing.category)editing.category=name;await save();categoryManager();refreshCategorySelect();toast('新分类已创建')});
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-page]');if(!t)return;if(t.dataset.page){returnContext=null;page=t.dataset.page;render();scrollTo(0,0)}else if(t.hasAttribute('data-add'))editor('',t.dataset.category||'');else if(t.dataset.edit)editor(t.dataset.edit);else if(t.hasAttribute('data-close'))close();else if(t.hasAttribute('data-delete')){if(confirm('确定删除这件物品？')){state.items=state.items.filter(i=>i.id!==editing.id);await save();close();render();toast('物品已删除')}}else if(t.dataset.check){const c=state.challenges.find(x=>x.id===t.dataset.check),today=dateKey();c.checks=c.checks.includes(today)?c.checks.filter(x=>x!==today):[...c.checks,today];await save();render();toast(c.checks.includes(today)?'今天打卡成功':'已取消今天的打卡')}else if(t.hasAttribute('data-new-challenge')){const name=prompt('挑战名称，例如：坚持不吃晚饭');if(name?.trim()){state.challenges.push({id:uid(),name:name.trim(),emoji:'✓',checks:[]});await save();render()}}else if(t.hasAttribute('data-export')){exportData();toast('完整备份已导出')}else if(t.hasAttribute('data-import'))$('#restoreFile').click()});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'&&!e.isComposing){query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(document.activeElement?.id==='search'){const input=$('#search'),pos=input.selectionStart;render();const next=$('#search');next?.focus();next?.setSelectionRange(pos,pos)}else render()},250)}});
document.addEventListener('change',async e=>{if(e.target.id==='categoryFilter'){category=e.target.value;subCategory='';Object.keys(fieldFilters).forEach(key=>fieldFilters[key]='');selectedItems.clear();render()}else if(e.target.dataset.fieldFilter){fieldFilters[e.target.dataset.fieldFilter]=e.target.value;selectedItems.clear();render()}else if(e.target.id==='itemCategory'){editing.category=e.target.value;$('#dynamicFields').innerHTML=dynamicFields(editing)}else if(e.target.id==='selectAllItems'){const visibleIds=[...document.querySelectorAll('[data-select-item]')].map(x=>x.dataset.selectItem);visibleIds.forEach(id=>e.target.checked?selectedItems.add(id):selectedItems.delete(id));render()}else if(e.target.dataset.selectItem){e.target.checked?selectedItems.add(e.target.dataset.selectItem):selectedItems.delete(e.target.dataset.selectItem);render()}else if(e.target.id==='photoInput'&&e.target.files[0]){editing.photo=await resizeImage(e.target.files[0]);document.querySelector('.photoPick').innerHTML=`<img src="${editing.photo}" alt=""><input id="photoInput" type="file" accept="image/*">`}else if(e.target.id==='restoreFile'&&e.target.files[0]){try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.items)||!Array.isArray(data.challenges))throw Error();if(!confirm(`将用备份中的 ${data.items.length} 件物品覆盖当前数据，确定继续？`))return;state=normalize(data);selectedItems.clear();await save();render();toast('备份恢复完成')}catch{toast('备份文件无法读取')}finally{e.target.value=''}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='itemForm')return;e.preventDefault();const f=new FormData(e.target);Object.assign(editing,{name:String(f.get('name')).trim(),category:f.get('category'),subcategory:String(f.get('subcategory')||'').trim(),usageStatus:String(f.get('usageStatus')||'').trim(),status:String(f.get('status')||'').trim(),season:String(f.get('season')||'').trim(),unit:String(f.get('unit')||'').trim(),purchaseChannel:String(f.get('purchaseChannel')||'').trim(),startDate:f.get('startDate'),price:f.get('price'),quantity:Number(f.get('quantity')||1),location:String(f.get('location')).trim(),expiryDate:f.get('expiryDate'),warrantyDate:f.get('warrantyDate'),notes:String(f.get('notes')).trim(),updatedAt:Date.now()});delete editing.purchaseDate;if(!editing.name)return toast('请填写物品名称');const exists=state.items.some(i=>i.id===editing.id);state.items=exists?state.items.map(i=>i.id===editing.id?editing:i):[editing,...state.items];await save();selectedItems.delete(editing.id);close();render();toast('已保存到本机')});

function itemRow(item){return`<button class="itemRow" data-edit="${item.id}"><span class="thumb">${item.photo?`<img src="${item.photo}" alt="">`:itemIcon(item.category)}</span><span><b>${esc(item.name)}</b><small>${esc(item.category)} · ${esc(itemSubcategory(item))} · ${daysHeld(item)}天</small></span><span class="cost">${money(dailyCost(item))}/天</span></button>`}
function itemCard(item){const details=[[itemSubcategory(item),'细分'],[item.usageStatus||item.status,'状态'],[item.season,'季节'],[item.unit,'单位'],[item.purchaseChannel,'途径']].filter(x=>x[0]&&x[0]!=='未分类');return`<article class="itemCard ${selectedItems.has(item.id)?'selected':''}"><label class="selectItem"><input type="checkbox" data-select-item="${item.id}" ${selectedItems.has(item.id)?'checked':''}><span>选择</span></label><button class="itemPhoto" data-edit="${item.id}">${item.photo?`<img src="${item.photo}" alt="${esc(item.name)}">`:itemIcon(item.category)}</button><div class="itemBody"><span class="badge">${esc(item.category)}</span>${expiryBadge(item)}<b>${esc(item.name)}</b><div class="itemTags">${details.map(([value,label])=>`<span><small>${label}</small>${esc(value)}</span>`).join('')}</div><div class="itemMeta"><span>持有 ${daysHeld(item)} 天</span><span>数量 ${Number(item.quantity||1)}${esc(item.unit||'')}</span></div><div class="itemMeta"><span>${money(item.price)}</span><strong>${money(dailyCost(item))}/天</strong></div></div></article>`}
function compactItem(item){const details=[itemSubcategory(item),item.usageStatus||item.status,item.season,item.unit,item.purchaseChannel].filter(x=>x&&x!=='未分类');return`<article class="compactItem ${selectedItems.has(item.id)?'selected':''}"><label><input type="checkbox" data-select-item="${item.id}" ${selectedItems.has(item.id)?'checked':''}></label><button data-edit="${item.id}"><span class="compactThumb">${item.photo?`<img src="${item.photo}" alt="">`:itemIcon(item.category)}</span><span class="compactIdentity"><b>${esc(item.name)}</b><small>${esc(item.category)}${details.length?` · ${details.map(esc).join(' · ')}`:''}</small></span><span class="compactMetrics"><small>持有 ${daysHeld(item)} 天</small><strong>${money(dailyCost(item))}/天</strong></span></button></article>`}

function categoryFieldProfile(cat){if(cat==='衣物')return['subcategory','usageStatus','season','unit'];if(cat==='数码')return['subcategory','status','purchaseChannel'];if(cat==='宠物用品'||cat==='宠物')return['subcategory'];if(cat==='护肤个护'||cat==='护肤彩妆个护')return['subcategory','usageStatus','purchaseChannel'];if(cat==='家用电器')return['subcategory','usageStatus','purchaseChannel'];if(cat==='杂物')return['subcategory','usageStatus'];return['subcategory']}
function fieldOptions(cat,field){const alias=cat==='宠物'?'宠物用品':cat==='护肤彩妆个护'?'护肤个护':cat;return state.fieldOptions?.[cat]?.[field]||state.fieldOptions?.[alias]?.[field]||defaultFieldOptions[alias]?.[field]||[]}
function dynamicField(item,field){const label=fieldLabels[field],values=fieldOptions(item.category,field),listId=`options-${field}-${String(item.category).replace(/[^\w\u4e00-\u9fff]/g,'')}`;return`<div class="field dynamicField"><div class="labelLine"><label>${label}</label><button type="button" class="miniTextBtn" data-manage-field="${field}" data-field-category="${esc(item.category)}">管理选项</button></div><input class="input" name="${field}" value="${esc(item[field]||'')}" list="${listId}" placeholder="选择或直接输入"><datalist id="${listId}">${values.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist></div>`}
function dynamicFields(item){return categoryFieldProfile(item.category).map(field=>dynamicField(item,field)).join('')}

function dashboardCalendar(){
  const y=dashboardMonth.getFullYear(),m=dashboardMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
  let cells='<span class="calendarBlank"></span>'.repeat(first);
  for(let d=1;d<=days;d++){
    const key=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,memos=state.memos.filter(x=>x.date===key);
    cells+=`<button class="memoDay ${key===dateKey()?'today':''}" data-memo-date="${key}"><b>${d}</b><span>${memos.slice(0,2).map(x=>`<i>${esc(x.text)}</i>`).join('')}</span>${memos.length>2?`<small>＋${memos.length-2}</small>`:''}</button>`;
  }
  return`<section class="panel calendarPanel"><div class="moduleHead"><div><span class="eyebrow">DAILY NOTES</span><h3>日历备忘</h3></div><div class="calendarNav"><button data-calendar-shift="-1" aria-label="上个月">‹</button><strong>${y}年${m+1}月</strong><button data-calendar-shift="1" aria-label="下个月">›</button></div></div><div class="weekHead">${['日','一','二','三','四','五','六'].map(x=>`<span>周${x}</span>`).join('')}</div><div class="memoCalendar">${cells}</div><p class="moduleHint">点击日期，可添加多条备忘。</p></section>`;
}

function electronicsModule(){
  const sorts={'days-desc':(a,b)=>daysHeld(b)-daysHeld(a),'days-asc':(a,b)=>daysHeld(a)-daysHeld(b),'cost-desc':(a,b)=>dailyCost(b)-dailyCost(a),'cost-asc':(a,b)=>dailyCost(a)-dailyCost(b)},items=state.items.filter(x=>x.category==='数码').sort(sorts[electronicsSort]||sorts['days-desc']);
  return`<section class="panel electronicsPanel"><div class="moduleHead electronicsHead"><div><span class="eyebrow">ELECTRONICS</span><h3>电子产品</h3></div><div class="electronicsActions"><div class="sortButtons" aria-label="电子产品排序"><button class="${electronicsSort==='days-desc'?'active':''}" data-electronics-sort="days-desc">天数 ↓</button><button class="${electronicsSort==='days-asc'?'active':''}" data-electronics-sort="days-asc">天数 ↑</button><button class="${electronicsSort==='cost-desc'?'active':''}" data-electronics-sort="cost-desc">成本 ↓</button><button class="${electronicsSort==='cost-asc'?'active':''}" data-electronics-sort="cost-asc">成本 ↑</button></div><button class="ghostBtn" data-open-category="数码">查看全部 ${items.length}</button></div></div><div class="dataTable"><div class="dataRow dataHeader"><span>名称</span><span>持有天数</span><span>日均成本</span></div>${items.length?items.map(item=>`<button class="dataRow" data-edit="${item.id}"><span><b>${esc(item.name)}</b><small>${esc(itemSubcategory(item))}</small></span><strong>${daysHeld(item).toLocaleString('zh-CN')} 天</strong><em>${money(dailyCost(item))}</em></button>`).join(''):'<div class="emptyMini">暂无电子产品记录</div>'}</div></section>`;
}

function clothingModule(){
 const clothes=state.items.filter(x=>x.category==='衣物');
 const groups=[...clothes.reduce((map,item)=>{const key=itemSubcategory(item),qty=Number(item.quantity||1);map.set(key,(map.get(key)||0)+qty);return map},new Map())].sort((a,b)=>b[1]-a[1]);
 const total=groups.reduce((n,x)=>n+x[1],0),palette=['#7991a8','#65704e','#a9af96','#e7c979','#8c7c80','#82b0af','#e8aac4','#7761a5','#f3818b','#cbd3df','#9d9bc8','#ffa44c','#4b5e70'];
 const cx=450,cy=218,outer=123,inner=78,polar=(r,angle)=>[cx+r*Math.cos(angle),cy+r*Math.sin(angle)];
 let start=-Math.PI/2;
 const arcs=groups.map(([name,count],i)=>{const span=count/total*Math.PI*2,end=start+span,large=span>Math.PI?1:0,p1=polar(outer,start),p2=polar(outer,end),q2=polar(inner,end),q1=polar(inner,start);const d=`M${p1.join(' ')} A${outer} ${outer} 0 ${large} 1 ${p2.join(' ')} L${q2.join(' ')} A${inner} ${inner} 0 ${large} 0 ${q1.join(' ')} Z`;start=end;return`<path d="${d}" fill="${palette[i%palette.length]}" stroke="#fffdf8" stroke-width="3"/>`}).join('');
 // Arrange callouts in two stable columns; avoid overlapping even for narrow slices.
 const left=groups.slice(0,Math.ceil(groups.length/2)),right=groups.slice(Math.ceil(groups.length/2));
 const callouts=(arr,side)=>arr.map(([name,count],i)=>{const n=arr.length,y=80+i*(n>1?276/(n-1):0),x=side==='left'?25:690,anchor=side==='left'?'start':'start',lineEnd=side==='left'?310:590,nearX=side==='left'?cx-outer:cx+outer;return`<g class="wardrobeCallout" data-clothing-group="${esc(name)}" role="button" tabindex="0"><path d="M${nearX} ${cy+(y-cy)*.55} L${side==='left'?295:605} ${y} L${lineEnd} ${y}" fill="none" stroke="#d6d8d5" stroke-width="1.6"/><circle cx="${x+7}" cy="${y-5}" r="5" fill="${palette[groups.findIndex(g=>g[0]===name)%palette.length]}"/><text x="${x+21}" y="${y}" font-size="17" fill="#28352e" text-anchor="${anchor}">${esc(name)}: ${count} (${(count/total*100).toFixed(2)}%)</text></g>`}).join('');
 return`<section class="panel clothingPanel"><div class="moduleHead"><div><span class="eyebrow">WARDROBE</span><h3>衣物分类</h3></div><button class="ghostBtn" data-open-category="衣物">查看全部 ${total} 件</button></div>${total?`<div class="wardrobeDiagram"><svg viewBox="0 0 900 425" role="img" aria-label="衣物分类环形统计图，共${total}件">${arcs}<circle cx="${cx}" cy="${cy}" r="${inner-3}" fill="#fffdf8"/><text x="${cx}" y="${cy+4}" text-anchor="middle" font-size="45" font-weight="750" fill="#24352d">${total}</text><text x="${cx}" y="${cy+34}" text-anchor="middle" font-size="17" fill="#667069">总数</text>${callouts(left,'left')}${callouts(right,'right')}</svg></div><div class="wardrobeMobileLegend">${groups.map(([name,count],i)=>`<button data-clothing-group="${esc(name)}"><i style="background:${palette[i%palette.length]}"></i><span>${esc(name)}</span><b>${count} (${(count/total*100).toFixed(2)}%)</b></button>`).join('')}</div>`:'<div class="emptyMini">暂无衣物记录</div>'}</section>`;
}
function categoryOverview(){
  const groups=categoryData(),visual=categoryDisplay==='visual';
  return`<section class="panel categoryOverview"><div class="moduleHead"><div><span class="eyebrow">CATEGORIES</span><h3>全部大类</h3></div><div class="viewSwitch"><button class="${visual?'active':''}" data-category-display="visual">图片</button><button class="${!visual?'active':''}" data-category-display="compact">紧凑</button></div></div><div class="${visual?'categoryVisual':'categoryCompact'}">${groups.map(([name,count])=>{const cover=state.items.find(x=>x.category===name&&x.photo)||state.items.find(x=>x.category===name);return`<button data-open-category="${esc(name)}">${visual?`<span class="categoryCover">${cover?.photo?`<img src="${cover.photo}" alt="">`:itemIcon(name)}</span>`:''}<span><b>${esc(name)}</b><small>${count} 条记录</small></span></button>`}).join('')}</div></section>`;
}

function dashboard(){
  const total=state.items.length,value=state.items.reduce((s,i)=>s+Number(i.price||0)*Number(i.quantity||1),0),expiring=state.items.filter(i=>i.expiryDate&&new Date(i.expiryDate)-Date.now()<30*86400000).length,avg=total?state.items.reduce((s,i)=>s+daysHeld(i),0)/total:0,recent=[...state.items].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,5),challenge=state.challenges[0]||{id:'no-spend',name:'不消费的一年',checks:[]},checked=challenge.checks.includes(dateKey()),yearProgress=Math.round(challenge.checks.filter(d=>d.startsWith(String(new Date().getFullYear()))).length/365*100);
  return`<div class="pageHead"><div><span class="eyebrow">HOUSEHOLD OVERVIEW</span><h2>把拥有的东西，过成明白的生活</h2><p>物品、成本、衣橱与每天的小事，都放在一个地方。</p></div><span class="dateBadge">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span></div><div class="dashboardModules">${dashboardCalendar()}${categoryOverview()}${dashboardChallenges()}${clothingModule()}${electronicsModule()}</div>`;
}

function itemsPage(){
  const scoped=state.items.filter(i=>category==='全部'||i.category===category),statusOf=i=>i.usageStatus||i.status||'',matches=(i,field)=>!fieldFilters[field]||(field==='subcategory'?itemSubcategory(i):field==='status'?statusOf(i):i[field])===fieldFilters[field],filtered=scoped.filter(i=>(!subCategory||itemSubcategory(i)===subCategory)&&Object.keys(fieldFilters).every(field=>matches(i,field))&&[i.name,i.category,itemSubcategory(i),statusOf(i),i.season,i.unit,i.purchaseChannel,i.location,i.notes].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  const selectedVisible=filtered.filter(x=>selectedItems.has(x.id)).length,allChecked=filtered.length&&selectedVisible===filtered.length;
  const options={subcategory:[...new Set(scoped.map(itemSubcategory).filter(x=>x&&x!=='未分类'))].sort(),status:[...new Set(scoped.map(statusOf).filter(Boolean))].sort(),season:[...new Set(scoped.map(i=>i.season).filter(Boolean))].sort(),unit:[...new Set(scoped.map(i=>i.unit).filter(Boolean))].sort(),purchaseChannel:[...new Set(scoped.map(i=>i.purchaseChannel).filter(Boolean))].sort()},select=(field,label)=>`<label class="filterField"><span>${label}</span><select class="select" data-field-filter="${field}"><option value="">全部</option>${options[field].map(v=>`<option value="${esc(v)}" ${fieldFilters[field]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
  return`${returnContext?`<button class="backButton" data-return-view>返回总览</button>`:''}<div class="pageHead"><div><span class="eyebrow">INVENTORY</span><h2>${subCategory?esc(subCategory):category!=='全部'?esc(category):'全部物品'}</h2><p>${category!=='全部'?`正在查看 ${esc(category)}${subCategory?` · ${esc(subCategory)}`:''}`:'查找全部字段，或按属性筛选。'}</p></div><div class="pageHeadActions"><div class="itemViewSwitch"><button class="${itemDisplay==='compact'?'active':''}" data-item-display="compact">紧凑</button><button class="${itemDisplay==='comfortable'?'active':''}" data-item-display="comfortable">图片</button></div><button class="ghostBtn" data-manage-categories>管理分类</button></div></div><div class="toolbar"><input id="search" class="input" value="${esc(query)}" placeholder="搜索名称、分类、状态、季节、单位、途径或备注"><select id="categoryFilter" class="select"><option>全部</option>${state.categories.map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>${subCategory?`<button class="filterChip" data-clear-subcategory>${esc(subCategory)} ×</button>`:''}<button class="primaryBtn" data-add>＋ 添加物品</button></div><div class="advancedFilters">${select('subcategory','细分品类')}${select('status','使用状态')}${select('season','适合季节')}${select('unit','单位')}${select('purchaseChannel','购买途径')}<button class="clearFilters" data-clear-field-filters>清除筛选</button></div>${filtered.length?`<div class="batchBar"><label><input type="checkbox" id="selectAllItems" ${allChecked?'checked':''}> 全选当前 ${filtered.length} 项</label><span>已选 <b>${selectedItems.size}</b> 项</span><button class="dangerSolid" data-batch-delete ${selectedItems.size?'':'disabled'}>删除所选</button></div>`:''}<div class="${itemDisplay==='compact'?'compactItems':'itemsGrid'}">${filtered.length?(itemDisplay==='compact'?filtered.map(compactItem):filtered.map(itemCard)).join(''):`<div class="empty" style="grid-column:1/-1"><b>没有找到物品</b><p>换个关键词或清除筛选条件。</p></div>`}</div>`;
}

function editor(id='',preset=''){
  const old=state.items.find(i=>i.id===id),fallback=state.categories[0]||'未分类',item=old?structuredClone(old):{id:uid(),name:'',category:preset&&state.categories.includes(preset)?preset:fallback,subcategory:'',usageStatus:'',status:'',season:'',unit:'',purchaseChannel:'',startDate:dateKey(),price:'',quantity:1,location:'',expiryDate:'',warrantyDate:'',notes:'',photo:'',createdAt:Date.now(),updatedAt:Date.now()};
  editing=item;document.body.insertAdjacentHTML('beforeend',`<section class="overlay"><form class="modal" id="itemForm"><div class="modalHead"><button type="button" class="ghostBtn" data-close>取消</button><h2>${old?'编辑物品':'新建物品'}</h2><button class="primaryBtn" type="submit">保存</button></div><div class="modalBody"><div class="formGrid"><div class="field full"><label>照片</label><label class="photoPick">${item.photo?`<img src="${item.photo}" alt="">`:'<span>＋ 添加物品照片</span>'}<input id="photoInput" type="file" accept="image/*"></label></div><div class="field"><label>名称 *</label><input class="input" name="name" value="${esc(item.name)}" required></div><div class="field"><div class="labelLine"><label>大类</label><button type="button" class="miniTextBtn" data-manage-categories>管理分类</button></div><select class="select" name="category" id="itemCategory">${state.categories.map(c=>`<option ${item.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div id="dynamicFields" class="dynamicFields full">${dynamicFields(item)}</div><div class="field"><label>使用日期</label><input class="input" name="startDate" type="date" value="${esc(item.startDate||item.purchaseDate||dateKey())}"></div><div class="field"><label>购买价格</label><input class="input" name="price" type="number" min="0" step="0.01" value="${esc(item.price)}"></div><div class="field"><label>数量</label><input class="input" name="quantity" type="number" min="1" value="${esc(item.quantity)}"></div><div class="field"><label>存放位置</label><input class="input" name="location" value="${esc(item.location)}"></div><div class="field"><label>有效期</label><input class="input" name="expiryDate" type="date" value="${esc(item.expiryDate)}"></div><div class="field"><label>保修截止</label><input class="input" name="warrantyDate" type="date" value="${esc(item.warrantyDate)}"></div><div class="field full"><label>备注</label><textarea class="textarea" name="notes">${esc(item.notes)}</textarea></div></div><div class="modalActions">${old?'<button type="button" class="dangerBtn" data-delete>删除物品</button>':'<span></span>'}<span>数据仅保存在当前浏览器</span></div></div></form></section>`);
}

function fieldOptionManager(cat,field){const values=fieldOptions(cat,field);document.body.insertAdjacentHTML('beforeend',`<section class="overlay fieldOptionOverlay"><div class="modal optionModal"><div class="modalHead"><button type="button" class="ghostBtn" data-close-field-options>完成</button><h2>${esc(cat)} · ${fieldLabels[field]}</h2><span>${values.length} 项</span></div><div class="modalBody"><form id="fieldOptionAdd" data-field="${field}" data-field-category="${esc(cat)}" class="categoryAdd"><input class="input" name="optionName" maxlength="30" placeholder="新增一个选项" required><button class="primaryBtn">＋ 新增</button></form><div class="optionList">${values.map((value,index)=>`<div class="optionRow"><span>${index+1}</span><input class="input" value="${esc(value)}"><button class="ghostBtn" data-rename-option="${esc(value)}" data-field="${field}" data-field-category="${esc(cat)}">保存</button><button class="dangerBtn" data-delete-option="${esc(value)}" data-field="${field}" data-field-category="${esc(cat)}">删除</button></div>`).join('')||'<div class="emptyMini">暂无选项，可在上方新增。</div>'}</div><p class="categoryHint">删除选项不会清空已有物品中的值；重命名会自动同步已有物品。</p></div></div></section>`)}

function memoEditor(date){
  const entries=state.memos.filter(x=>x.date===date).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0));
  document.body.insertAdjacentHTML('beforeend',`<section class="overlay memoOverlay"><form class="modal memoModal" id="memoForm" data-date="${date}"><div class="modalHead"><button type="button" class="ghostBtn" data-close>取消</button><h2>${date} 备忘</h2><button class="primaryBtn" type="submit">添加</button></div><div class="modalBody"><div class="memoExisting">${entries.length?entries.map(x=>`<div><span>${esc(x.text)}</span><button type="button" data-delete-memo="${x.id}">删除</button></div>`).join(''):'<p>这一天还没有备忘。</p>'}</div><div class="field full"><label>新增备忘</label><textarea class="textarea" name="memoText" required placeholder="每行一条，例如：\n没有花钱\n拉屎了\n买了1杯星巴克"></textarea><small>可一次输入多行，每行保存为一条记录。</small></div></div></form></section>`);
}

document.addEventListener('click',async e=>{
  const t=e.target.closest('button');if(!t)return;
  if(t.dataset.calendarShift){dashboardMonth=new Date(dashboardMonth.getFullYear(),dashboardMonth.getMonth()+Number(t.dataset.calendarShift),1);render()}
  else if(t.dataset.memoDate)memoEditor(t.dataset.memoDate);
  else if(t.dataset.categoryDisplay){categoryDisplay=t.dataset.categoryDisplay;render()}
  else if(t.dataset.electronicsSort){electronicsSort=t.dataset.electronicsSort;render()}
  else if(t.dataset.itemDisplay){itemDisplay=t.dataset.itemDisplay;render()}
  else if(t.dataset.openCategory){openInventoryFromDashboard(t.dataset.openCategory)}
  else if(t.dataset.clothingGroup){openInventoryFromDashboard('衣物',t.dataset.clothingGroup)}
  else if(t.hasAttribute('data-return-view')){if(location.hash==='#inventory')history.back();else restorePreviousView()}
  else if(t.hasAttribute('data-clear-subcategory')){subCategory='';render()}
  else if(t.hasAttribute('data-clear-field-filters')){Object.keys(fieldFilters).forEach(key=>fieldFilters[key]='');render()}
  else if(t.dataset.deleteMemo){state.memos=state.memos.filter(x=>x.id!==t.dataset.deleteMemo);await save();const date=t.closest('form')?.dataset.date;close();memoEditor(date);toast('备忘已删除')}
  else if(t.dataset.manageField){fieldOptionManager(t.dataset.fieldCategory,t.dataset.manageField)}
  else if(t.hasAttribute('data-close-field-options')){document.querySelector('.fieldOptionOverlay')?.remove();if(editing&&$('#dynamicFields'))$('#dynamicFields').innerHTML=dynamicFields(editing)}
  else if(t.dataset.renameOption!==undefined){const cat=t.dataset.fieldCategory,field=t.dataset.field,old=t.dataset.renameOption,next=t.closest('.optionRow').querySelector('input').value.trim();if(!next)return toast('选项不能为空');const values=fieldOptions(cat,field);if(next!==old&&values.includes(next))return toast('该选项已存在');state.fieldOptions[cat]??={};state.fieldOptions[cat][field]=values.map(x=>x===old?next:x);state.items=state.items.map(item=>item.category===cat&&item[field]===old?{...item,[field]:next}:item);if(editing?.category===cat&&editing[field]===old)editing[field]=next;await save();document.querySelector('.fieldOptionOverlay')?.remove();fieldOptionManager(cat,field);toast('选项已更新')}
  else if(t.dataset.deleteOption!==undefined){const cat=t.dataset.fieldCategory,field=t.dataset.field,value=t.dataset.deleteOption;if(!confirm(`删除选项“${value}”？已有物品中的该值会保留。`))return;state.fieldOptions[cat][field]=fieldOptions(cat,field).filter(x=>x!==value);await save();document.querySelector('.fieldOptionOverlay')?.remove();fieldOptionManager(cat,field);toast('选项已删除')}
  else if(t.hasAttribute('data-batch-delete')){if(!selectedItems.size)return;if(!confirm(`确定删除已选择的 ${selectedItems.size} 件物品？此操作无法撤销。`))return;state.items=state.items.filter(item=>!selectedItems.has(item.id));const count=selectedItems.size;selectedItems.clear();await save();render();toast(`已删除 ${count} 件物品`)}
  else if(t.dataset.secondaryCategory){secondaryManager(t.dataset.secondaryCategory)}
  else if(t.hasAttribute('data-close-secondary')){document.querySelector('.secondaryOverlay')?.remove()}
});

document.addEventListener('submit',async e=>{
  if(e.target.id!=='memoForm')return;e.preventDefault();
  const date=e.target.dataset.date,lines=String(new FormData(e.target).get('memoText')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),now=Date.now();
  if(!lines.length)return;
  state.memos.push(...lines.map((text,index)=>({id:uid(),date,text,createdAt:now+index,updatedAt:now+index})));
  await save();close();render();toast(`已添加 ${lines.length} 条备忘`);
});

document.addEventListener('submit',async e=>{if(e.target.id!=='fieldOptionAdd')return;e.preventDefault();const f=new FormData(e.target),cat=e.target.dataset.fieldCategory,field=e.target.dataset.field,name=String(f.get('optionName')||'').trim();if(!name)return;const values=fieldOptions(cat,field);if(values.includes(name))return toast('该选项已存在');state.fieldOptions[cat]??={};state.fieldOptions[cat][field]=[...values,name];await save();document.querySelector('.fieldOptionOverlay')?.remove();fieldOptionManager(cat,field);toast('新选项已添加')});

document.addEventListener('change',e=>{if(e.target.id==='categoryFilter'){subCategory=''}});
addEventListener('popstate',()=>{if(returnContext)restorePreviousView()});
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.challengeDetail){e.stopImmediatePropagation();challengeMonth=new Date();challengeDetail(t.dataset.challengeDetail)}else if(t.dataset.deleteChallenge){e.stopImmediatePropagation();const c=state.challenges.find(x=>x.id===t.dataset.deleteChallenge);if(!c||!confirm(`删除挑战“${c.name}”及其全部打卡记录？`))return;state.challenges=state.challenges.filter(x=>x.id!==c.id);await save();render();toast('挑战已删除')}else if(t.hasAttribute('data-close-challenge-detail')){e.stopImmediatePropagation();document.querySelector('.challengeDetailOverlay')?.remove()}else if(t.dataset.challengeMonth){e.stopImmediatePropagation();challengeMonth=new Date(challengeMonth.getFullYear(),challengeMonth.getMonth()+Number(t.dataset.challengeMonth),1);challengeDetail(t.dataset.challengeId)}else if(t.dataset.challengeDate){e.stopImmediatePropagation();const c=state.challenges.find(x=>x.id===t.dataset.challengeId);if(!c)return;const key=t.dataset.challengeDate;c.checks=c.checks.includes(key)?c.checks.filter(x=>x!==key):[...c.checks,key];await save();challengeDetail(c.id);toast('打卡记录已更新')}},true);
async function init(){db=await openDB();const saved=await dbGet();state=normalize(saved||state);render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(console.warn)}
init().catch(err=>{$('#app').innerHTML=`<div class="empty"><b>无法打开本地数据库</b><p>${esc(err.message)}</p></div>`});

// SVG chart callouts support mouse, touch and keyboard selection.
document.addEventListener('click',e=>{const target=e.target.closest?.('svg [data-clothing-group]');if(target)openInventoryFromDashboard('衣物',target.dataset.clothingGroup)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('svg [data-clothing-group]')){e.preventDefault();openInventoryFromDashboard('衣物',e.target.dataset.clothingGroup)}});
